380	static void
381	measure_power_dbm(void)
382	{
383	  extern int log2_q31(int32_t x);
384	  int agcgain = uistat.rfgain;
385	  if (uistat.agcmode != AGC_MANUAL)
386	    agcgain = tlv320aic3204_get_left_agc_gain();
387	  
388	  int dbm =                    // fixed point 8.8 format
389	    6 * log2_q31(stat.rms[0])  // 6dB/bit
390	    - (agcgain << 7);          // 0.5dB/agcgain
391	  dbm -= 116 << 8;
392	  measured_power_dbm = dbm;
393	}
