924	    /* yb' = (ya-xb-yc+xd)co1 + (xa+yb-xc-yd)(si1) */
925	    pSrc[(2u * i2) + 1u] = (((int32_t) (((q63_t) s1 * co1) >> 32)) +
926	                            ((int32_t) (((q63_t) r1 * si1) >> 32))) << 1u;
