937	    /* yd' = (ya+xb-yc-xd)co3 + (xa-yb-xc+yd)(si3) */
938	    pSrc[(2u * i3) + 1u] = (((int32_t) (((q63_t) s2 * co3) >> 32)) +
939	                            ((int32_t) (((q63_t) r2 * si3) >> 32))) << 1u;
940	
941	    /*  Twiddle coefficients index modifier */
